window.ICA_CONTENT["picco"] = {"origin":{"status":"source_verified_clinical_review_pending","reviewed":"2026-10-06","entity":"device","unverified":0,"audited":26},"langs":["tr","en","es"],"gaps":[{"tr":"Getinge PiCCO/Pulsiocare kullanım kılavuzu (IFU) çevrimiçi erişilemedi; enjektat hacmi ve sıcaklığı, pediatrik kullanım ve alarm ayarları kullanılan cihazın IFU’su ile ayrıca teyit edilmelidir.","en":"The Getinge PiCCO/Pulsiocare instructions for use (IFU) could not be accessed online; injectate volume and temperature, paediatric use and alarm settings must be confirmed with the IFU of the device in use.","es":"No se pudo acceder en línea a las instrucciones de uso (IFU) de Getinge PiCCO/Pulsiocare; el volumen y la temperatura del inyectado, el uso pediátrico y la configuración de alarmas deben confirmarse con las IFU del dispositivo utilizado."},{"tr":"Referans değerler üreticinin genel bilgilendirme materyalinden alınmıştır; üretici bu değerleri belirli bir hasta için önermez ve materyal IFU’nun yerini tutmaz.","en":"Reference values are taken from the manufacturer’s general information material; the manufacturer does not recommend them for a specific patient and the material does not replace the IFU.","es":"Los valores de referencia proceden del material informativo general del fabricante; el fabricante no los recomienda para un paciente concreto y el material no sustituye a las IFU."},{"tr":"Bu kayıt için tüm model/sensör/sürüm eşleşmeleri ve klinik editör onayı tamamlanmadı.","en":"Model/sensor/version mapping and clinical editor approval for this record are not yet complete.","es":"La correspondencia completa de modelos/sensores/versiones y la aprobación del editor clínico de este registro aún no se han completado."},{"tr":"Görselleri yeniden yayımlama hakkı ve 3B geometrinin doğruluğu ayrıca doğrulanmalıdır.","en":"Image republication rights and exact 3D geometry require separate verification.","es":"Los derechos para volver a publicar las imágenes y la geometría 3D exacta requieren una verificación independiente."}],"animation":{"ready":false,"reason":{"tr":"Model ile sensörün tam uyumu ve tüm anatomik referanslar klinik editör tarafından henüz doğrulanmadı. Temsilî SVG koordinatları anatomik koordinatları göstermez.","en":"The exact model/sensor mapping and all anatomical references have not been verified by a clinical editor. Representative SVG coordinates are not anatomical coordinates.","es":"La compatibilidad exacta entre el modelo y el sensor, así como todas las referencias anatómicas, aún no ha sido verificada por un editor clínico. Las coordenadas SVG representativas no son coordenadas anatómicas."},"scope":{"tr":"Bilgi yok","en":"No data available","es":"Sin datos disponibles"}},"sections":{"overview":{"tr":"PiCCO, transpulmoner termodilüsyon (transpulmonary thermodilution, TPTD) ile nabız kontur analizini birleştiren ileri hemodinamik monitörizasyon teknolojisidir; Getinge Pulsiocare monitörüne entegre olarak sunulur. [3]\n\nPiCCO-2 için FDA’ya bildirilen kullanım amacı, kardiyopulmoner ve dolaşım değişkenlerinin belirlenmesi ve izlenmesidir: kardiyak debi nabız kontur analiziyle sürekli, termodilüsyonla aralıklı ölçülür; termodilüsyon eğrisinin analizinden intravasküler ve ekstravasküler sıvı hacimleri türetilir. [11] TPTD’nin ayırt edici yönü, ekstravasküler akciğer suyunun ve pulmoner vasküler geçirgenliğin yatak başında tahmin edilebilmesidir. [9]","en":"PiCCO is an advanced haemodynamic monitoring technology that combines transpulmonary thermodilution (TPTD) with pulse contour analysis; it is integrated into the Getinge Pulsiocare monitor. [3]\n\nThe intended use submitted to the FDA for PiCCO-2 is the determination and monitoring of cardiopulmonary and circulatory variables: cardiac output is measured continuously by pulse contour analysis and intermittently by thermodilution, and intravascular and extravascular fluid volumes are derived from analysis of the thermodilution curve. [11] A distinctive feature of TPTD is the bedside estimation of extravascular lung water and pulmonary vascular permeability. [9]","es":"PiCCO es una tecnología de monitorización hemodinámica avanzada que combina la termodilución transpulmonar (TDTP) con el análisis del contorno del pulso; está integrada en el monitor Getinge Pulsiocare. [3]\n\nEl uso previsto declarado ante la FDA para PiCCO-2 es la determinación y monitorización de variables cardiopulmonares y circulatorias: el gasto cardiaco se mide de forma continua mediante análisis del contorno del pulso y de forma intermitente mediante termodilución, y los volúmenes de líquido intravascular y extravascular se derivan del análisis de la curva de termodilución. [11] Un rasgo distintivo de la TDTP es la estimación a pie de cama del agua pulmonar extravascular y de la permeabilidad vascular pulmonar. [9]"},"principle":{"tr":"Santral venöz yola (tercihen superior vena kava bölgesine) soğuk salin bolusu enjekte edilir; arter kateterinin ucundaki termistör kan sıcaklığındaki düşüşü algılar ve kardiyak debi Stewart–Hamilton ilkesiyle hesaplanır. [9]\n\nTermodilüsyonla ölçülen debi, nabız kontur analizinin kalibrasyonunda kullanılır; böylece debi sürekli izlenebilir. [9] [11] Termodilüsyon eğrisinin ortalama geçiş süresi ve iniş eğimi süresinden intravasküler ve ekstravasküler hacimler türetilir; boy ve ağırlık girilirse türetilen parametreler vücut yüzey alanına indekslenir. [11] Monnet ve Teboul, debi değeri yorum için gerekliyse son kalibrasyondan 1 saat veya daha uzun süre geçtiğinde yeniden kalibrasyon yapılmasını önerir. [9]\n\nBolus hacmi ve sıcaklığı üretici talimatına göre seçilir; uygulanan enjektat hacminin cihaza doğru girilmesi parametre hesabı için zorunludur. [10] Bu kayıtta invaziv kateter takma tekniği anlatılmaz.","en":"A cold saline bolus is injected into a central venous line (preferably in the superior vena cava territory); a thermistor at the tip of an arterial catheter detects the fall in blood temperature, and cardiac output is calculated using the Stewart–Hamilton principle. [9]\n\nThe thermodilution cardiac output is used to calibrate pulse contour analysis, enabling continuous cardiac output monitoring. [9] [11] Intravascular and extravascular volumes are derived from the mean transit time and downslope time of the thermodilution curve; if height and weight are entered, derived parameters are indexed to body surface area. [11] Monnet and Teboul recommend recalibration when cardiac output is needed for interpretation and 1 h or more has elapsed since the last calibration. [9]\n\nBolus volume and temperature are selected according to the manufacturer’s instructions; correct entry of the applied injectate volume into the device is mandatory for parameter calculation. [10] Invasive catheter insertion technique is not described in this record.","es":"Se inyecta un bolo de solución salina fría por una vía venosa central (preferentemente en el territorio de la vena cava superior); un termistor en la punta de un catéter arterial detecta el descenso de la temperatura sanguínea y el gasto cardiaco se calcula según el principio de Stewart–Hamilton. [9]\n\nEl gasto cardiaco obtenido por termodilución se utiliza para calibrar el análisis del contorno del pulso, lo que permite monitorizar el gasto cardiaco de forma continua. [9] [11] Los volúmenes intravasculares y extravasculares se derivan del tiempo de tránsito medio y del tiempo de caída exponencial de la curva de termodilución; si se introducen la talla y el peso, los parámetros derivados se indexan a la superficie corporal. [11] Monnet y Teboul recomiendan recalibrar cuando el gasto cardiaco es necesario para la interpretación y ha transcurrido 1 h o más desde la última calibración. [9]\n\nEl volumen y la temperatura del bolo se seleccionan según las instrucciones del fabricante; la introducción correcta en el dispositivo del volumen de inyectado aplicado es obligatoria para el cálculo de los parámetros. [10] Este registro no describe la técnica de inserción de catéteres invasivos."},"placement":{"tr":"1. Termodilüsyon bolusu için santral venöz kateter gerekir; enjeksiyon tercihen distal lümenden yapılır. Bolus femoral venden de verilebilir; ancak bu durumda GEDV normal değerleri superior vena kava yoluna göre daha yüksektir. [9] [10]\n2. Termistörlü PiCCO arter kateteri santrale yakın bir artere, tercihen femoral artere yerleştirilir; alternatif olarak brakiyal veya aksiller arter ya da uzun radiyal kateterle radiyal arter kullanılabilir. Standart periferik radiyal arter kateteriyle PiCCO ölçümü çalışmaz. [10]\n3. Enjektat sensör yuvası santral venöz kateter lümenine 90 derece açıyla monte edilir; yuva ile kateter lümeni arasında ek uzatma veya üç yollu musluk bulunmamalıdır. Enjeksiyon lümeninden, özellikle vazoaktif veya inotrop ilaç infüzyonu yapılmamalıdır. [10]\n4. Basınç transdüseri kalp seviyesine konumlandırılır, basınç hattı yıkanır ve sıfırlama yapılır. [10]\n\nKesin anatomik mesafe, sağ/sol montaj ayrıntısı ve 3B koordinat: Bilgi yok.","en":"1. A central venous catheter is required for the thermodilution bolus; injection is preferably made through the distal lumen. The bolus can also be given via a femoral venous catheter, but GEDV normal values are then higher than with the superior vena cava route. [9] [10]\n2. The thermistor-tipped PiCCO arterial catheter is placed in a central (near-aortic) artery, preferably the femoral artery; alternatively the brachial or axillary artery, or the radial artery with a long radial catheter, can be used. PiCCO measurement does not work with a standard peripheral radial arterial catheter. [10]\n3. The injectate sensor housing is mounted on the central venous catheter lumen at a 90-degree angle; there should be no additional extensions or stopcocks between the housing and the catheter lumen. Drugs, especially vasoactive or inotropic agents, must not be infused through the injection lumen. [10]\n4. The pressure transducer is positioned at heart level, the pressure line is flushed and zeroing is performed. [10]\n\nExact anatomical distances, right/left mounting details and 3D coordinates: No data available.","es":"1. Se requiere un catéter venoso central para el bolo de termodilución; la inyección se realiza preferentemente por la luz distal. El bolo también puede administrarse por un catéter venoso femoral, pero en ese caso los valores normales de GEDV son más altos que con la vía de la vena cava superior. [9] [10]\n2. El catéter arterial PiCCO con termistor se coloca en una arteria central (próxima a la aorta), preferentemente la arteria femoral; como alternativa pueden usarse la arteria braquial o axilar, o la arteria radial con un catéter radial largo. La medición PiCCO no funciona con un catéter arterial radial periférico estándar. [10]\n3. La carcasa del sensor del líquido inyectado se monta en la luz del catéter venoso central en un ángulo de 90 grados; no debe haber alargaderas ni llaves de tres vías adicionales entre la carcasa y la luz del catéter. No deben infundirse fármacos, especialmente vasoactivos o inotrópicos, por la luz de inyección. [10]\n4. El transductor de presión se coloca a la altura del corazón, se purga la línea de presión y se realiza la puesta a cero. [10]\n\nDistancias anatómicas exactas, detalles de montaje derecho/izquierdo y coordenadas 3D: Sin datos disponibles."},"use":{"tr":"1. Kateter uyumunu ve santral venöz/arteriyel hat bağlantılarını kontrol edin. [10]\n2. Hasta verilerini (kategori, cinsiyet, doğum tarihi, boy, ağırlık) doğru girin. [10]\n3. Sürekli CVP ölçümü yoksa cihaz varsayılan CVP değerini (5 mmHg) kullanır; gerçek CVP belirgin farklıysa değer güncellenmelidir. [10]\n4. Termodilüsyon ölçümünü, üreticinin kalite ölçütlerine göre en az üç uygun ölçüm elde edilene ve değerlerin ortalamadan sapması %15’in altında kalana kadar tekrarlayın. [10] Üç bolus sonucunun ortalamasının alınması önerilir. [9]\n5. Sürekli nabız kontur analizi, invaziv arter basıncı sinyalinin yeterli kalitede olmasını gerektirir. [10]\n\nModele özgü açma sırası, kalibrasyon menüsü ve sayısal alarm limitleri: Modele ve yazılım sürümüne göre değişir; kullanılan cihazın IFU’suna bakın.","en":"1. Check catheter compatibility and the central venous/arterial line connections. [10]\n2. Enter patient data (category, sex, date of birth, height, weight) correctly. [10]\n3. If CVP is not measured continuously, the device uses a default CVP value (5 mmHg); this value should be updated when the actual CVP differs significantly. [10]\n4. Repeat thermodilution until at least three acceptable measurements are obtained, with deviations from the mean below 15%, according to the manufacturer’s quality criteria. [10] Averaging the results of three bolus injections is recommended. [9]\n5. Continuous pulse contour analysis requires an invasive arterial pressure signal of sufficient quality. [10]\n\nModel-specific start-up sequence, calibration menu and numerical alarm limits: These vary by model and software version; refer to the IFU of the device in use.","es":"1. Compruebe la compatibilidad del catéter y las conexiones de las vías venosa central y arterial. [10]\n2. Introduzca correctamente los datos del paciente (categoría, sexo, fecha de nacimiento, talla, peso). [10]\n3. Si la PVC no se mide de forma continua, el dispositivo utiliza un valor de PVC por defecto (5 mmHg); este valor debe actualizarse cuando la PVC real difiera de forma significativa. [10]\n4. Repita la termodilución hasta obtener al menos tres mediciones aceptables, con desviaciones respecto a la media inferiores al 15%, según los criterios de calidad del fabricante. [10] Se recomienda promediar los resultados de tres bolos. [9]\n5. El análisis continuo del contorno del pulso requiere una señal de presión arterial invasiva de calidad suficiente. [10]\n\nSecuencia de encendido específica del modelo, menú de calibración y límites numéricos de alarma: Varían según el modelo y la versión de software; consulte las IFU del dispositivo utilizado."},"params":{"tr":"| Parametre | Birim | Aralık | Hedef / normal | Anlamı |\n|---|---|---|---|---|\n| Kardiyak debi (cardiac output) CO | L/dk | Bilgi yok | İndekslenmemiş mutlak değer; üretici normal aralık vermez, trend için kullanılır. [8] | Kalbin bir dakikada pompaladığı kan hacmi. [1] |\n| Kardiyak indeks (cardiac index) CI | L/dk/m² | Bilgi yok | Üretici erişkin referansı: 3,0–5,0; tedavi hedefi değildir. [8] | Kardiyak debinin vücut yüzey alanına bölünmüş değeri. [1] |\n| Atım hacmi (stroke volume) SV / SVI | mL; mL/m² | Bilgi yok | SVI üretici erişkin referansı: 40–60 mL/m²; SV için normal aralık verilmez. [8] | Her kalp atımında pompalanan kan hacmi; SVI vücut yüzey alanına indekslenmiş değeridir. [1] |\n| SVR / SVRI | dyn·s·cm⁻⁵; dyn·s·cm⁻⁵·m² | Bilgi yok | SVRI üretici erişkin referansı: 1700–2400; tedavi hedefi değildir. [8] | Sistemik dolaşımda kan akımına karşı direncin hesaplanan göstergesi. [1] |\n| SVV (stroke volume variation) | % | Bilgi yok | Bilgi yok | Atım hacminin maksimum ve minimum değerleri arasındaki farkın ortalamaya göre yüzdesi. [1] |\n| PPV (pulse pressure variation) | % | Bilgi yok | Bilgi yok | Nabız basıncının maksimum ve minimum değerleri arasındaki farkın ortalamaya göre yüzdesi. [1] |\n| GEDI (global end-diastolic volume index) | mL/m² | Bilgi yok | Üretici erişkin referansı: 680–800; tedavi hedefi değildir. [8] | Global end-diyastolik hacim indeksi; dört kalp boşluğunun diyastol sonundaki toplam hacmi. [9] |\n| ELWI (extravascular lung water index) | mL/kg | Bilgi yok | Üretici erişkin referansı: 3,0–7,0; tedavi hedefi değildir. [8] | Ekstravasküler akciğer suyu indeksi; akciğer ödeminin nicel göstergesi. [9] |\n| PVPI (pulmonary vascular permeability index) | oran | Bilgi yok | Üretici referansı: 1,0–3,0; tek başına tanı koydurmaz. [8] | EVLW’nin pulmoner kan hacmine oranı; alveolokapiller geçirgenlik göstergesi. [9] |\n\n[1] [8] [9]","en":"| Parameter | Unit | Range | Target / normal | Meaning |\n|---|---|---|---|---|\n| Cardiac output CO | L/min | No data available | Non-indexed absolute value; the manufacturer gives no normal range, used for trends. [8] | Volume of blood pumped by the heart per minute. [1] |\n| Cardiac index CI | L/min/m² | No data available | Manufacturer adult reference: 3.0–5.0; not a treatment target. [8] | Cardiac output divided by body surface area. [1] |\n| Stroke volume SV / SVI | mL; mL/m² | No data available | SVI manufacturer adult reference: 40–60 mL/m²; no normal range given for SV. [8] | Volume of blood ejected with each heartbeat; SVI is the value indexed to body surface area. [1] |\n| SVR / SVRI | dyn·s·cm⁻⁵; dyn·s·cm⁻⁵·m² | No data available | SVRI manufacturer adult reference: 1700–2400; not a treatment target. [8] | Calculated index of resistance to blood flow in the systemic circulation. [1] |\n| SVV (stroke volume variation) | % | No data available | No data available | Difference between maximum and minimum stroke volume expressed as a percentage of the mean. [1] |\n| PPV (pulse pressure variation) | % | No data available | No data available | Difference between maximum and minimum pulse pressure expressed as a percentage of the mean. [1] |\n| GEDI (global end-diastolic volume index) | mL/m² | No data available | Manufacturer adult reference: 680–800; not a treatment target. [8] | Global end-diastolic volume index; total volume of the four cardiac chambers at end-diastole. [9] |\n| ELWI (extravascular lung water index) | mL/kg | No data available | Manufacturer adult reference: 3.0–7.0; not a treatment target. [8] | Extravascular lung water index; quantitative marker of pulmonary oedema. [9] |\n| PVPI (pulmonary vascular permeability index) | ratio | No data available | Manufacturer reference: 1.0–3.0; not diagnostic on its own. [8] | Ratio of EVLW to pulmonary blood volume; marker of alveolar–capillary permeability. [9] |\n\n[1] [8] [9]","es":"| Parámetro | Unidad | Rango | Objetivo / normal | Significado |\n|---|---|---|---|---|\n| Gasto cardiaco GC (CO) | L/min | Sin datos disponibles | Valor absoluto no indexado; el fabricante no da rango normal, se usa para tendencias. [8] | Volumen de sangre que bombea el corazón por minuto. [1] |\n| Índice cardiaco IC (CI) | L/min/m² | Sin datos disponibles | Referencia del fabricante en adultos: 3,0–5,0; no es un objetivo terapéutico. [8] | Gasto cardiaco dividido por la superficie corporal. [1] |\n| Volumen sistólico VS / IVS (SV / SVI) | mL; mL/m² | Sin datos disponibles | Referencia del fabricante para SVI en adultos: 40–60 mL/m²; no se da rango normal para SV. [8] | Volumen de sangre eyectado en cada latido; el SVI es el valor indexado a la superficie corporal. [1] |\n| SVR / SVRI | dyn·s·cm⁻⁵; dyn·s·cm⁻⁵·m² | Sin datos disponibles | Referencia del fabricante para SVRI en adultos: 1700–2400; no es un objetivo terapéutico. [8] | Índice calculado de la resistencia al flujo sanguíneo en la circulación sistémica. [1] |\n| SVV (variación del volumen sistólico) | % | Sin datos disponibles | Sin datos disponibles | Diferencia entre el volumen sistólico máximo y mínimo expresada como porcentaje de la media. [1] |\n| PPV (variación de la presión de pulso) | % | Sin datos disponibles | Sin datos disponibles | Diferencia entre la presión de pulso máxima y mínima expresada como porcentaje de la media. [1] |\n| GEDI (índice de volumen telediastólico global) | mL/m² | Sin datos disponibles | Referencia del fabricante en adultos: 680–800; no es un objetivo terapéutico. [8] | Índice de volumen telediastólico global; volumen total de las cuatro cavidades cardiacas al final de la diástole. [9] |\n| ELWI (índice de agua pulmonar extravascular) | mL/kg | Sin datos disponibles | Referencia del fabricante en adultos: 3,0–7,0; no es un objetivo terapéutico. [8] | Índice de agua pulmonar extravascular; marcador cuantitativo del edema pulmonar. [9] |\n| PVPI (índice de permeabilidad vascular pulmonar) | cociente | Sin datos disponibles | Referencia del fabricante: 1,0–3,0; no es diagnóstico por sí solo. [8] | Cociente entre EVLW y volumen sanguíneo pulmonar; marcador de permeabilidad alveolocapilar. [9] |\n\n[1] [8] [9]"},"eval":{"tr":"**Kardiyak debi CO:** İndekslenmemiş mutlak değerler için üretici normal aralık vermez; bunlar trend izleminde kullanılır. [8] Debi; ScvO2, laktat ve perfüzyon (MAP) bulgularıyla birlikte yorumlanır. [8]\n\n**Kardiyak indeks CI:** Üretici erişkin referansı 3,0–5,0 L/dk/m²’dir. [8] Üretici bu değerleri belirli bir hasta için önermediğini belirtir; referans aralık tek başına resüsitasyon (resuscitation) hedefi değildir. [8]\n\n**Atım hacmi SV / SVI:** SVI için üretici erişkin referansı 40–60 mL/m²’dir; indekslenmemiş SV için normal aralık verilmez. [8] Sıvı yanıtlılığı pasif bacak kaldırma, ekspirasyon sonu oklüzyon testi, sıvı yüklemesi testi ya da uygun koşullarda SVV/PPV ile değerlendirilir. [8] [6]\n\n**SVR / SVRI:** SVRI ard yükün (afterload) hesaplanmış göstergesidir; üretici erişkin referansı 1700–2400 dyn·s·cm⁻⁵·m²’dir. [8] SVR = 80 × (MAP − CVP)/CO; SVRI aynı formülde CO yerine CI kullanır. [1] CVP veya debi yanlışsa hesaplanan direnç de yanlış olur; sürekli CVP ölçülmüyorsa cihaz varsayılan CVP değerini kullanır. [10]\n\n**SVV:** Sıvı yanıtlılığı değerlendirmesinde ancak uygun koşullarda kullanılır. Spontan solunum, aritmi, düşük tidal hacim veya düşük akciğer kompliyansı güvenilirliği sınırlar. [6] Üretici, SVV ve PPV’nin yalnızca tam kontrollü ventilasyonda, tidal hacim ≥8 mL/kg öngörülen vücut ağırlığı (PBW) iken ve aritmi yokken uygulanabileceğini; %10’un altındaki değerde sıvıya yanıtın olası olmadığını, %13’ün üzerindeki değerde olası olduğunu belirtir. [8] Sıvıya yanıtlı olmak tek başına sıvı verme endikasyonu değildir; olası yarar ve sıvı yüklenmesi riski birlikte değerlendirilir. [6]\n\n**PPV:** Sıvı yanıtlılığı değerlendirmesinde ancak uygun koşullarda kullanılır. Spontan solunum, aritmi, düşük tidal hacim veya düşük akciğer kompliyansı güvenilirliği sınırlar. [6] Üretici, SVV ve PPV’nin yalnızca tam kontrollü ventilasyonda, tidal hacim ≥8 mL/kg öngörülen vücut ağırlığı (PBW) iken ve aritmi yokken uygulanabileceğini; %10’un altındaki değerde sıvıya yanıtın olası olmadığını, %13’ün üzerindeki değerde olası olduğunu belirtir. [8] Sıvıya yanıtlı olmak tek başına sıvı verme endikasyonu değildir; olası yarar ve sıvı yüklenmesi riski birlikte değerlendirilir. [6]\n\n**GEDI:** Üretici erişkin referansı 680–800 mL/m²’dir; kalp ön yükünün (preload) hacimsel göstergesidir. [8] [9] Tüm statik ön yük göstergeleri gibi GEDV de sıvı yanıtlılığının zayıf bir göstergesidir. [9] Bolus femoral venden verildiğinde GEDV değerleri superior vena kava yoluna göre yüksektir. [9]\n\n**ELWI:** Üretici erişkin referansı 3,0–7,0 mL/kg’dır; artış akciğer ödemini gösterir. [8] [9] EVLW, olduğundan düşük tahmin edilmemesi için gerçek değil öngörülen vücut ağırlığına indekslenir; EVLW’de anlamlı kabul edilebilecek en küçük değişim %12’dir. [9] Ödemin hidrostatik mi geçirgenlik kaynaklı mı olduğu ELWI ile değil, PVPI ile ayırt edilmeye çalışılır. [9]\n\n**PVPI:** Üretici referansı 1,0–3,0’dır. [8] PVPI hidrostatik ödemde ARDS’ye göre daha düşüktür; 3 değeri iki ödem türünü ayırmada en iyi eşik olarak bulunmuştur. [9] ARDS tanısı klinik tanım ölçütlerine (Berlin tanımı) dayanır; PVPI yalnızca destekleyici bilgi sağlar. [12]\n\nKaynakla doğrulanmış örnek klinik senaryo: Bilgi yok.","en":"**Cardiac output CO:** The manufacturer gives no normal range for non-indexed absolute values; these are used for trend monitoring. [8] Cardiac output is interpreted together with ScvO2, lactate and perfusion (MAP). [8]\n\n**Cardiac index CI:** Manufacturer adult reference 3.0–5.0 L/min/m². [8] The manufacturer states that it does not recommend these values for a specific patient; the reference range is not by itself a resuscitation target. [8]\n\n**Stroke volume SV / SVI:** Manufacturer adult reference for SVI is 40–60 mL/m²; no normal range is given for non-indexed SV. [8] Fluid responsiveness is assessed with passive leg raising, an end-expiratory occlusion test, a fluid challenge or, under appropriate conditions, SVV/PPV. [8] [6]\n\n**SVR / SVRI:** SVRI is a calculated index of afterload; the manufacturer adult reference is 1700–2400 dyn·s·cm⁻⁵·m². [8] SVR = 80 × (MAP − CVP)/CO; SVRI uses CI instead of CO in the same formula. [1] If CVP or cardiac output is wrong, the calculated resistance is also wrong; when CVP is not measured continuously, the device uses a default CVP value. [10]\n\n**SVV:** Used for assessing fluid responsiveness only under appropriate conditions. Spontaneous breathing, arrhythmia, low tidal volume or low lung compliance limit its reliability. [6] The manufacturer states that SVV and PPV are applicable only in fully controlled ventilation with a tidal volume ≥8 mL/kg predicted body weight (PBW) and without arrhythmia; below 10% the patient is unlikely, and above 13% likely, to be fluid responsive. [8] Being fluid responsive is not by itself an indication for fluid administration; potential benefit and the risk of fluid overload are weighed together. [6]\n\n**PPV:** Used for assessing fluid responsiveness only under appropriate conditions. Spontaneous breathing, arrhythmia, low tidal volume or low lung compliance limit its reliability. [6] The manufacturer states that SVV and PPV are applicable only in fully controlled ventilation with a tidal volume ≥8 mL/kg predicted body weight (PBW) and without arrhythmia; below 10% the patient is unlikely, and above 13% likely, to be fluid responsive. [8] Being fluid responsive is not by itself an indication for fluid administration; potential benefit and the risk of fluid overload are weighed together. [6]\n\n**GEDI:** Manufacturer adult reference 680–800 mL/m²; it is a volumetric marker of cardiac preload. [8] [9] Like all static preload markers, GEDV is a poor indicator of fluid responsiveness. [9] When the bolus is injected via the femoral vein, GEDV values are higher than with the superior vena cava route. [9]\n\n**ELWI:** Manufacturer adult reference 3.0–7.0 mL/kg; an increase indicates pulmonary oedema. [8] [9] EVLW is indexed to predicted rather than actual body weight to avoid underestimation; the least significant change in EVLW is 12%. [9] Whether oedema is hydrostatic or permeability-related is assessed with PVPI, not ELWI. [9]\n\n**PVPI:** Manufacturer reference 1.0–3.0. [8] PVPI is lower in hydrostatic pulmonary oedema than in ARDS; a value of 3 was the best threshold for distinguishing the two. [9] ARDS is diagnosed by clinical definition criteria (Berlin Definition); PVPI provides supportive information only. [12]\n\nSource-verified example clinical scenario: No data available.","es":"**Gasto cardiaco GC (CO):** El fabricante no da rango normal para los valores absolutos no indexados; se utilizan para el seguimiento de tendencias. [8] El gasto cardiaco se interpreta junto con la ScvO2, el lactato y la perfusión (PAM). [8]\n\n**Índice cardiaco IC (CI):** Referencia del fabricante en adultos: 3,0–5,0 L/min/m². [8] El fabricante indica que no recomienda estos valores para un paciente concreto; el rango de referencia no es por sí solo un objetivo de reanimación. [8]\n\n**Volumen sistólico SV / SVI:** La referencia del fabricante para SVI en adultos es 40–60 mL/m²; no se da rango normal para el SV no indexado. [8] La respuesta a volumen se valora con elevación pasiva de piernas, prueba de oclusión teleespiratoria, prueba de carga de volumen o, en condiciones adecuadas, SVV/PPV. [8] [6]\n\n**SVR / SVRI:** El SVRI es un índice calculado de la poscarga; la referencia del fabricante en adultos es 1700–2400 dyn·s·cm⁻⁵·m². [8] SVR = 80 × (PAM − PVC)/GC; el SVRI usa el IC en lugar del GC en la misma fórmula. [1] Si la PVC o el gasto cardiaco son erróneos, la resistencia calculada también lo es; cuando la PVC no se mide de forma continua, el dispositivo utiliza un valor de PVC por defecto. [10]\n\n**SVV:** Se utiliza para valorar la respuesta a volumen solo en condiciones adecuadas. La respiración espontánea, las arritmias, el volumen corriente bajo o la distensibilidad pulmonar baja limitan su fiabilidad. [6] El fabricante indica que SVV y PPV solo son aplicables con ventilación totalmente controlada, volumen corriente ≥8 mL/kg de peso corporal predicho (PBW) y sin arritmias; por debajo del 10% es improbable, y por encima del 13% probable, que el paciente responda a volumen. [8] Responder a volumen no constituye por sí solo una indicación de administrar líquidos; se valoran conjuntamente el posible beneficio y el riesgo de sobrecarga hídrica. [6]\n\n**PPV:** Se utiliza para valorar la respuesta a volumen solo en condiciones adecuadas. La respiración espontánea, las arritmias, el volumen corriente bajo o la distensibilidad pulmonar baja limitan su fiabilidad. [6] El fabricante indica que SVV y PPV solo son aplicables con ventilación totalmente controlada, volumen corriente ≥8 mL/kg de peso corporal predicho (PBW) y sin arritmias; por debajo del 10% es improbable, y por encima del 13% probable, que el paciente responda a volumen. [8] Responder a volumen no constituye por sí solo una indicación de administrar líquidos; se valoran conjuntamente el posible beneficio y el riesgo de sobrecarga hídrica. [6]\n\n**GEDI:** Referencia del fabricante en adultos: 680–800 mL/m²; es un marcador volumétrico de la precarga cardiaca. [8] [9] Como todos los marcadores estáticos de precarga, el GEDV es un mal indicador de la respuesta a volumen. [9] Cuando el bolo se inyecta por la vena femoral, los valores de GEDV son más altos que con la vía de la vena cava superior. [9]\n\n**ELWI:** Referencia del fabricante en adultos: 3,0–7,0 mL/kg; su aumento indica edema pulmonar. [8] [9] El EVLW se indexa al peso corporal predicho y no al real para evitar su infraestimación; el cambio mínimo significativo del EVLW es del 12%. [9] El carácter hidrostático o por aumento de permeabilidad del edema se valora con el PVPI, no con el ELWI. [9]\n\n**PVPI:** Referencia del fabricante: 1,0–3,0. [8] El PVPI es menor en el edema pulmonar hidrostático que en el SDRA; un valor de 3 fue el mejor umbral para distinguir ambos. [9] El SDRA se diagnostica con criterios clínicos de definición (definición de Berlín); el PVPI solo aporta información de apoyo. [12]\n\nEscenario clínico de ejemplo verificado con fuentes: Sin datos disponibles."},"trouble":{"tr":"- Enjektat hacminin cihaza yanlış girilmesi veya yanlış uygulanması, sensör yuvası ile kateter arasında ek uzatma/musluk bulunması ya da enjeksiyon lümeninden ilaç infüzyonu termodilüsyon ölçümünü bozar. [10]\n- Soldan sağa intrakardiyak şantta CI büyük olasılıkla doğrudur (hafifçe düşük olabilir), GEDI ve ELWI olduğundan yüksek ölçülebilir; sağdan sola şantta tüm termodilüsyon sonuçları kuşkuludur. [10]\n- Kapak yetersizliğinde CI ve ELWI doğru kabul edilir; GEDI olduğundan yüksek ölçülebilir. [10]\n- Abdominal aort anevrizmasında CI ve ELWI geçerlidir; GEDI olduğundan yüksek ölçülebilir. [10]\n- Pulmoner perfüzyon bozukluğunda (ör. pulmoner emboli) ELWI olduğundan düşük ölçülebilir. [10] [9] Akciğer rezeksiyonu sonrası kalan EVLW ve büyük plevral efüzyonda EVLW olduğundan yüksek tahmin edilebilir. [9]\n- Yanlış kateter yeri: Standart periferik radiyal kateterle PiCCO ölçümü çalışmaz; femoral venden enjeksiyon GEDV değerlerini yükseltir. [10] [9]\n- Bozuk arter dalgası: Ağır aritmi sürekli (nabız kontur) parametrelerini bozabilir, termodilüsyon ölçümü aritmiden etkilenmez. [10] Sistolde çift tepe görülürse basınç hattı yıkanır, gerekirse sönümleme artırılır ve sıfırlama yapılır. [10]\n- Femoral arter kateterinde en sık komplikasyon lokal hematomdur; iskemi, nabız kaybı ve femoral arter trombozu nadir ve geçici olarak bildirilmiştir. [9]\n- GEDI sıvı yanıtının doğrudan testi değildir. [9]\n- TPTD, ekstrakorporeal membran oksijenasyonu (ECMO) sırasında kullanılamaz. [9]","en":"- Incorrect entry or application of the injectate volume, additional extensions/stopcocks between the sensor housing and the catheter, or drug infusion through the injection lumen impair thermodilution measurement. [10]\n- With a left-to-right intracardiac shunt, CI is most likely correct (possibly slightly underestimated) while GEDI and ELWI may be overestimated; with a right-to-left shunt, all thermodilution results are doubtful. [10]\n- With valvular insufficiency, CI and ELWI should be correct; GEDI may be overestimated. [10]\n- With abdominal aortic aneurysm, CI and ELWI are valid; GEDI may be overestimated. [10]\n- With pulmonary perfusion disturbances (e.g. pulmonary embolism), ELWI may be underestimated. [10] [9] After lung resection the remaining EVLW, and with large pleural effusions EVLW, may be overestimated. [9]\n- Incorrect catheter site: PiCCO measurement does not work with a standard peripheral radial catheter; femoral venous injection raises GEDV values. [10] [9]\n- Distorted arterial waveform: severe arrhythmia may impair continuous (pulse contour) parameters, whereas thermodilution is not affected by arrhythmia. [10] If double peaks appear in systole, flush the pressure line, increase damping if needed and re-zero. [10]\n- The most common complication of the femoral arterial catheter is local haematoma; ischaemia, pulse loss and femoral artery thrombosis have been reported as uncommon and transient. [9]\n- GEDI is not a direct test of fluid responsiveness. [9]\n- TPTD cannot be used during extracorporeal membrane oxygenation (ECMO). [9]","es":"- La introducción o aplicación incorrecta del volumen de inyectado, las alargaderas/llaves adicionales entre la carcasa del sensor y el catéter o la infusión de fármacos por la luz de inyección alteran la medición por termodilución. [10]\n- En un cortocircuito intracardiaco izquierda-derecha, el IC probablemente es correcto (quizá algo infraestimado), mientras que GEDI y ELWI pueden sobrestimarse; en un cortocircuito derecha-izquierda, todos los resultados de termodilución son dudosos. [10]\n- En la insuficiencia valvular, IC y ELWI deberían ser correctos; el GEDI puede sobrestimarse. [10]\n- En el aneurisma de aorta abdominal, IC y ELWI son válidos; el GEDI puede sobrestimarse. [10]\n- En los trastornos de la perfusión pulmonar (p. ej., embolia pulmonar), el ELWI puede infraestimarse. [10] [9] Tras una resección pulmonar el EVLW remanente, y en derrames pleurales grandes el EVLW, pueden sobrestimarse. [9]\n- Localización incorrecta del catéter: la medición PiCCO no funciona con un catéter radial periférico estándar; la inyección por vena femoral eleva los valores de GEDV. [10] [9]\n- Onda arterial alterada: las arritmias graves pueden alterar los parámetros continuos (contorno del pulso), mientras que la termodilución no se ve afectada por la arritmia. [10] Si aparecen dobles picos en sístole, se purga la línea de presión, se aumenta la amortiguación si es necesario y se repite la puesta a cero. [10]\n- La complicación más frecuente del catéter arterial femoral es el hematoma local; la isquemia, la pérdida de pulso y la trombosis de la arteria femoral se han descrito como infrecuentes y transitorias. [9]\n- El GEDI no es una prueba directa de respuesta a volumen. [9]\n- La TDTP no puede utilizarse durante la oxigenación por membrana extracorpórea (ECMO). [9]"},"special":{"tr":"- **ECMO:** TPTD, ekstrakorporeal membran oksijenasyonu sırasında kullanılamaz. [9]\n- **Sürekli venövenöz hemofiltrasyon:** TPTD ile debi ölçümünün güvenilirliğini etkilemediği bildirilmiştir. [9]\n- **Terapötik hipotermi:** Debi ölçümünün kesinliğini etkilemediği bildirilmiştir. [9]\n- **Ağır hipovolemili yanık hastaları:** Bir merkezde alt ekstremitede geçici iskemi sıklığının literatürde bildirilen %0,4’ten yüksek olduğu raporlanmıştır. [13]\n- **Pediatrik hastalar:** Kateter boyutu, enjektat hacmi ve referans değerler modele ve yazılıma göre değişir; kullanılan cihazın IFU’suna bakın.","en":"- **ECMO:** TPTD cannot be used during extracorporeal membrane oxygenation. [9]\n- **Continuous veno-venous haemofiltration:** Reported not to affect the reliability of TPTD cardiac output measurement. [9]\n- **Therapeutic hypothermia:** Reported not to affect the precision of cardiac output measurement. [9]\n- **Burn patients with severe hypovolaemia:** One centre reported a higher incidence of transient lower-limb ischaemia than the 0.4% reported in the literature. [13]\n- **Paediatric patients:** Catheter size, injectate volume and reference values vary by model and software; refer to the IFU of the device in use.","es":"- **ECMO:** La TDTP no puede utilizarse durante la oxigenación por membrana extracorpórea. [9]\n- **Hemofiltración venovenosa continua:** Se ha descrito que no afecta a la fiabilidad de la medición del gasto cardiaco por TDTP. [9]\n- **Hipotermia terapéutica:** Se ha descrito que no afecta a la precisión de la medición del gasto cardiaco. [9]\n- **Pacientes quemados con hipovolemia grave:** Un centro comunicó una incidencia de isquemia transitoria de miembros inferiores superior al 0,4% descrito en la literatura. [13]\n- **Pacientes pediátricos:** El tamaño del catéter, el volumen de inyectado y los valores de referencia varían según el modelo y el software; consulte las IFU del dispositivo utilizado."},"roles":{"tr":"Aşağıdaki başlıklar, her meslek grubu için önerilen öğrenme konularını gösterir; mevzuatta tanımlanan mesleki yetki ve sorumlulukları belirlemez.\n\n- **Teknisyen:** Eğitim odağı: uyumlu sarf malzemelerinin ve bağlantıların hazırlanması, kontrol listesinin kullanılması ve yeniden kullanıma hazırlama işlemleri. Yeniden kullanılabilir parçaların temizliği, dezenfeksiyon veya sterilizasyon öncesinde yapılır; kullanılacak kimyasal madde ve yöntem, malzemenin özelliklerine ve üreticinin talimatlarına göre seçilir. [7]\n- **Asistan:** Eğitim odağı: parametrenin tanımı, sinyal kalitesi, sık yapılan yorum hataları ve sorumlu uzmanla olgu değerlendirmesi.\n- **Uzman:** Eğitim odağı: klinik bağlam, yöntemin sınırlamaları ve kanıtın uygulamaya aktarılması.\n\n[7]","en":"The following sections suggest learning objectives for each professional group; they do not define professional responsibilities or scope of practice under applicable regulations.\n\n- **Technician:** Training focus: preparation of compatible consumables and connections, checklists and reprocessing. Reusable parts are cleaned before disinfection or sterilisation; the agent and method are selected according to the material and the manufacturer's instructions. [7]\n- **Resident:** Training focus: parameter definitions, signal quality, common interpretation errors and case review with the responsible specialist.\n- **Specialist:** Training focus: clinical context, limitations of the method and translating evidence into practice.\n\n[7]","es":"La distribución de funciones siguiente es un diseño educativo del atlas; no es una definición normativa de competencias profesionales.\n\n- **Técnico:** Enfoque formativo: preparación de consumibles y conexiones compatibles, listas de verificación y reprocesamiento. Las piezas reutilizables se limpian antes de la desinfección o esterilización; el producto y el método se eligen según el material y las instrucciones del fabricante. [7]\n- **Residente:** Enfoque formativo: definición de los parámetros, calidad de la señal, errores frecuentes de interpretación y revisión de casos con el especialista responsable.\n- **Especialista:** Enfoque formativo: contexto clínico, limitaciones del método y aplicación de la evidencia a la práctica.\n\n[7]"}},"params":[{"label":{"tr":"Kardiyak debi CO","en":"Cardiac output CO","es":"Gasto cardiaco GC (CO)"},"unit":{"tr":"L/dk","en":"L/min","es":"L/min"},"meaning":{"tr":"Kalbin bir dakikada pompaladığı kan hacmi.","en":"Volume of blood pumped by the heart per minute.","es":"Volumen de sangre que bombea el corazón por minuto."},"interpretation":{"tr":"İndekslenmemiş mutlak değerler için üretici normal aralık vermez; trend izleminde kullanılır. [8]","en":"The manufacturer gives no normal range for non-indexed absolute values; they are used for trend monitoring. [8]","es":"El fabricante no da rango normal para los valores absolutos no indexados; se usan para el seguimiento de tendencias. [8]"},"context":{"tr":"ScvO2, laktat ve perfüzyon (MAP) bulgularıyla birlikte yorumlanır. [8]","en":"Interpreted together with ScvO2, lactate and perfusion (MAP). [8]","es":"Se interpreta junto con la ScvO2, el lactato y la perfusión (PAM). [8]"},"range":{"tr":"Bilgi yok","en":"No data available","es":"Sin datos disponibles"},"target":{"tr":"Bilgi yok","en":"No data available","es":"Sin datos disponibles"},"numeric":null,"verify":{"definition":"source_supported","interpretation":"source_supported","numeric":"not_verified"}},{"label":{"tr":"Kardiyak indeks CI","en":"Cardiac index CI","es":"Índice cardiaco IC (CI)"},"unit":{"tr":"L/dk/m²","en":"L/min/m²","es":"L/min/m²"},"meaning":{"tr":"Kardiyak debinin vücut yüzey alanına bölünmüş değeri.","en":"Cardiac output divided by body surface area.","es":"Gasto cardiaco dividido por la superficie corporal."},"interpretation":{"tr":"Üretici erişkin referansı 3,0–5,0 L/dk/m². [8]","en":"Manufacturer adult reference 3.0–5.0 L/min/m². [8]","es":"Referencia del fabricante en adultos: 3,0–5,0 L/min/m². [8]"},"context":{"tr":"Üretici bu değerleri belirli bir hasta için önermez; referans aralık tek başına resüsitasyon hedefi değildir. [8]","en":"The manufacturer does not recommend these values for a specific patient; the reference range is not by itself a resuscitation target. [8]","es":"El fabricante no recomienda estos valores para un paciente concreto; el rango de referencia no es por sí solo un objetivo de reanimación. [8]"},"range":{"tr":"Bilgi yok","en":"No data available","es":"Sin datos disponibles"},"target":{"tr":"Üretici erişkin referansı: 3,0–5,0; tedavi hedefi değildir. [8]","en":"Manufacturer adult reference: 3.0–5.0; not a treatment target. [8]","es":"Referencia del fabricante en adultos: 3,0–5,0; no es un objetivo terapéutico. [8]"},"numeric":{"type":"manufacturer_reference","population":"adult"},"verify":{"definition":"source_supported","interpretation":"source_supported","numeric":"source_supported_context_limited"}},{"label":{"tr":"Atım hacmi SV / SVI","en":"Stroke volume SV / SVI","es":"Volumen sistólico SV / SVI"},"unit":{"tr":"mL; mL/m²","en":"mL; mL/m²","es":"mL; mL/m²"},"meaning":{"tr":"Her kalp atımında pompalanan kan hacmi; SVI vücut yüzey alanına indekslenmiş değeridir.","en":"Volume of blood ejected with each heartbeat; SVI is the value indexed to body surface area.","es":"Volumen de sangre eyectado en cada latido; el SVI es el valor indexado a la superficie corporal."},"interpretation":{"tr":"Sıvı yanıtlılığı pasif bacak kaldırma, ekspirasyon sonu oklüzyon testi, sıvı yüklemesi testi ya da uygun koşullarda SVV/PPV ile değerlendirilir. [8] [6]","en":"Fluid responsiveness is assessed with passive leg raising, an end-expiratory occlusion test, a fluid challenge or, under appropriate conditions, SVV/PPV. [8] [6]","es":"La respuesta a volumen se valora con elevación pasiva de piernas, prueba de oclusión teleespiratoria, prueba de carga de volumen o, en condiciones adecuadas, SVV/PPV. [8] [6]"},"context":{"tr":"SV indekslenmemiş mutlak değerdir ve üretici bunun için normal aralık vermez; normal aralık yalnızca SVI için verilir. [8]","en":"SV is a non-indexed absolute value for which the manufacturer gives no normal range; a normal range is given only for SVI. [8]","es":"El SV es un valor absoluto no indexado para el que el fabricante no da rango normal; solo se da rango normal para el SVI. [8]"},"range":{"tr":"Bilgi yok","en":"No data available","es":"Sin datos disponibles"},"target":{"tr":"SVI üretici erişkin referansı: 40–60 mL/m²; tedavi hedefi değildir. [8]","en":"SVI manufacturer adult reference: 40–60 mL/m²; not a treatment target. [8]","es":"Referencia del fabricante para SVI en adultos: 40–60 mL/m²; no es un objetivo terapéutico. [8]"},"numeric":{"type":"manufacturer_reference","population":"adult"},"verify":{"definition":"source_supported","interpretation":"source_supported","numeric":"source_supported_context_limited"}},{"label":{"tr":"SVR / SVRI","en":"SVR / SVRI","es":"SVR / SVRI"},"unit":{"tr":"dyn·s·cm⁻⁵; dyn·s·cm⁻⁵·m²","en":"dyn·s·cm⁻⁵; dyn·s·cm⁻⁵·m²","es":"dyn·s·cm⁻⁵; dyn·s·cm⁻⁵·m²"},"meaning":{"tr":"Sistemik dolaşımda kan akımına karşı direncin hesaplanan göstergesi.","en":"Calculated index of resistance to blood flow in the systemic circulation.","es":"Índice calculado de la resistencia al flujo sanguíneo en la circulación sistémica."},"interpretation":{"tr":"SVRI ard yükün hesaplanmış göstergesidir; üretici erişkin referansı 1700–2400 dyn·s·cm⁻⁵·m². [8]","en":"SVRI is a calculated index of afterload; manufacturer adult reference 1700–2400 dyn·s·cm⁻⁵·m². [8]","es":"El SVRI es un índice calculado de la poscarga; referencia del fabricante en adultos: 1700–2400 dyn·s·cm⁻⁵·m². [8]"},"context":{"tr":"SVR = 80 × (MAP−CVP)/CO; SVRI’de CO yerine CI kullanılır. [1] Yanlış CVP veya debi hesabı bozar; sürekli CVP ölçülmüyorsa cihaz varsayılan CVP değerini kullanır. [10]","en":"SVR = 80 × (MAP−CVP)/CO; SVRI uses CI instead of CO. [1] An incorrect CVP or cardiac output distorts the calculation; when CVP is not measured continuously, the device uses a default CVP value. [10]","es":"SVR = 80 × (PAM−PVC)/GC; el SVRI usa el IC en lugar del GC. [1] Una PVC o un gasto cardiaco erróneos alteran el cálculo; cuando la PVC no se mide de forma continua, el dispositivo utiliza un valor de PVC por defecto. [10]"},"range":{"tr":"Bilgi yok","en":"No data available","es":"Sin datos disponibles"},"target":{"tr":"SVRI üretici erişkin referansı: 1700–2400; tedavi hedefi değildir. [8]","en":"SVRI manufacturer adult reference: 1700–2400; not a treatment target. [8]","es":"Referencia del fabricante para SVRI en adultos: 1700–2400; no es un objetivo terapéutico. [8]"},"numeric":{"type":"manufacturer_reference","population":"adult"},"verify":{"definition":"source_supported","interpretation":"source_supported","numeric":"source_supported_context_limited"}},{"label":{"tr":"SVV","en":"SVV","es":"SVV"},"unit":{"tr":"%","en":"%","es":"%"},"meaning":{"tr":"Atım hacminin maksimum ve minimum değerleri arasındaki farkın ortalamaya göre yüzdesi.","en":"Difference between maximum and minimum stroke volume expressed as a percentage of the mean.","es":"Diferencia entre el volumen sistólico máximo y mínimo expresada como porcentaje de la media."},"interpretation":{"tr":"Sıvı yanıtlılığı değerlendirmesinde ancak uygun koşullarda kullanılır. Spontan solunum, aritmi, düşük tidal hacim veya düşük akciğer kompliyansı güvenilirliği sınırlar. [6] Üretici notu: yalnızca tam kontrollü ventilasyonda, tidal hacim ≥8 mL/kg PBW iken ve aritmi yokken uygulanabilir; <%10 sıvıya yanıt olası değil, >%13 olası. [8]","en":"Used for assessing fluid responsiveness only under appropriate conditions. Spontaneous breathing, arrhythmia, low tidal volume or low lung compliance limit its reliability. [6] Manufacturer note: applicable only in fully controlled ventilation with tidal volume ≥8 mL/kg PBW and without arrhythmia; <10% fluid responsiveness unlikely, >13% likely. [8]","es":"Se utiliza para valorar la respuesta a volumen solo en condiciones adecuadas. La respiración espontánea, las arritmias, el volumen corriente bajo o la distensibilidad pulmonar baja limitan su fiabilidad. [6] Nota del fabricante: solo aplicable con ventilación totalmente controlada, volumen corriente ≥8 mL/kg PBW y sin arritmias; <10% respuesta a volumen improbable, >13% probable. [8]"},"context":{"tr":"Sıvıya yanıtlı olmak tek başına sıvı verme endikasyonu değildir; olası yarar ve sıvı yüklenmesi riski birlikte değerlendirilir. [6]","en":"Being fluid responsive is not by itself an indication for fluid administration; potential benefit and the risk of fluid overload are weighed together. [6]","es":"Responder a volumen no constituye por sí solo una indicación de administrar líquidos; se valoran conjuntamente el posible beneficio y el riesgo de sobrecarga hídrica. [6]"},"range":{"tr":"Bilgi yok","en":"No data available","es":"Sin datos disponibles"},"target":{"tr":"Bilgi yok","en":"No data available","es":"Sin datos disponibles"},"numeric":null,"verify":{"definition":"source_supported","interpretation":"source_supported","numeric":"not_verified"}},{"label":{"tr":"PPV","en":"PPV","es":"PPV"},"unit":{"tr":"%","en":"%","es":"%"},"meaning":{"tr":"Nabız basıncının maksimum ve minimum değerleri arasındaki farkın ortalamaya göre yüzdesi.","en":"Difference between maximum and minimum pulse pressure expressed as a percentage of the mean.","es":"Diferencia entre la presión de pulso máxima y mínima expresada como porcentaje de la media."},"interpretation":{"tr":"Sıvı yanıtlılığı değerlendirmesinde ancak uygun koşullarda kullanılır. Spontan solunum, aritmi, düşük tidal hacim veya düşük akciğer kompliyansı güvenilirliği sınırlar. [6] Üretici notu: yalnızca tam kontrollü ventilasyonda, tidal hacim ≥8 mL/kg PBW iken ve aritmi yokken uygulanabilir; <%10 sıvıya yanıt olası değil, >%13 olası. [8]","en":"Used for assessing fluid responsiveness only under appropriate conditions. Spontaneous breathing, arrhythmia, low tidal volume or low lung compliance limit its reliability. [6] Manufacturer note: applicable only in fully controlled ventilation with tidal volume ≥8 mL/kg PBW and without arrhythmia; <10% fluid responsiveness unlikely, >13% likely. [8]","es":"Se utiliza para valorar la respuesta a volumen solo en condiciones adecuadas. La respiración espontánea, las arritmias, el volumen corriente bajo o la distensibilidad pulmonar baja limitan su fiabilidad. [6] Nota del fabricante: solo aplicable con ventilación totalmente controlada, volumen corriente ≥8 mL/kg PBW y sin arritmias; <10% respuesta a volumen improbable, >13% probable. [8]"},"context":{"tr":"Sıvıya yanıtlı olmak tek başına sıvı verme endikasyonu değildir; olası yarar ve sıvı yüklenmesi riski birlikte değerlendirilir. [6]","en":"Being fluid responsive is not by itself an indication for fluid administration; potential benefit and the risk of fluid overload are weighed together. [6]","es":"Responder a volumen no constituye por sí solo una indicación de administrar líquidos; se valoran conjuntamente el posible beneficio y el riesgo de sobrecarga hídrica. [6]"},"range":{"tr":"Bilgi yok","en":"No data available","es":"Sin datos disponibles"},"target":{"tr":"Bilgi yok","en":"No data available","es":"Sin datos disponibles"},"numeric":null,"verify":{"definition":"source_supported","interpretation":"source_supported","numeric":"not_verified"}},{"label":{"tr":"GEDI","en":"GEDI","es":"GEDI"},"unit":{"tr":"mL/m²","en":"mL/m²","es":"mL/m²"},"meaning":{"tr":"Global end-diyastolik hacim indeksi; dört kalp boşluğunun diyastol sonundaki toplam hacmi. [9]","en":"Global end-diastolic volume index; total volume of the four cardiac chambers at end-diastole. [9]","es":"Índice de volumen telediastólico global; volumen total de las cuatro cavidades cardiacas al final de la diástole. [9]"},"interpretation":{"tr":"Üretici erişkin referansı 680–800 mL/m²; kalp ön yükünün hacimsel göstergesidir. [8] [9]","en":"Manufacturer adult reference 680–800 mL/m²; volumetric marker of cardiac preload. [8] [9]","es":"Referencia del fabricante en adultos: 680–800 mL/m²; marcador volumétrico de la precarga cardiaca. [8] [9]"},"context":{"tr":"Statik ön yük göstergesi olarak sıvı yanıtlılığının zayıf bir göstergesidir; femoral venden enjeksiyonda değerler daha yüksektir. [9]","en":"As a static preload marker it is a poor indicator of fluid responsiveness; values are higher with femoral venous injection. [9]","es":"Como marcador estático de precarga es un mal indicador de la respuesta a volumen; los valores son más altos con inyección por vena femoral. [9]"},"range":{"tr":"Bilgi yok","en":"No data available","es":"Sin datos disponibles"},"target":{"tr":"Üretici erişkin referansı: 680–800; tedavi hedefi değildir. [8]","en":"Manufacturer adult reference: 680–800; not a treatment target. [8]","es":"Referencia del fabricante en adultos: 680–800; no es un objetivo terapéutico. [8]"},"numeric":{"type":"manufacturer_reference","population":"adult"},"verify":{"definition":"source_supported","interpretation":"source_supported","numeric":"source_supported_context_limited"}},{"label":{"tr":"ELWI","en":"ELWI","es":"ELWI"},"unit":{"tr":"mL/kg","en":"mL/kg","es":"mL/kg"},"meaning":{"tr":"Ekstravasküler akciğer suyu indeksi; akciğer ödeminin nicel göstergesi. [9]","en":"Extravascular lung water index; quantitative marker of pulmonary oedema. [9]","es":"Índice de agua pulmonar extravascular; marcador cuantitativo del edema pulmonar. [9]"},"interpretation":{"tr":"Üretici erişkin referansı 3,0–7,0 mL/kg; artış akciğer ödemini gösterir. [8] [9]","en":"Manufacturer adult reference 3.0–7.0 mL/kg; an increase indicates pulmonary oedema. [8] [9]","es":"Referencia del fabricante en adultos: 3,0–7,0 mL/kg; su aumento indica edema pulmonar. [8] [9]"},"context":{"tr":"Öngörülen vücut ağırlığına indekslenir; ödem tipinin (hidrostatik/geçirgenlik) ayrımı ELWI ile değil PVPI ile yapılmaya çalışılır. [9]","en":"Indexed to predicted body weight; the type of oedema (hydrostatic/permeability) is assessed with PVPI, not ELWI. [9]","es":"Se indexa al peso corporal predicho; el tipo de edema (hidrostático/por permeabilidad) se valora con el PVPI, no con el ELWI. [9]"},"range":{"tr":"Bilgi yok","en":"No data available","es":"Sin datos disponibles"},"target":{"tr":"Üretici erişkin referansı: 3,0–7,0; tedavi hedefi değildir. [8]","en":"Manufacturer adult reference: 3.0–7.0; not a treatment target. [8]","es":"Referencia del fabricante en adultos: 3,0–7,0; no es un objetivo terapéutico. [8]"},"numeric":{"type":"manufacturer_reference","population":"adult"},"verify":{"definition":"source_supported","interpretation":"source_supported","numeric":"source_supported_context_limited"}},{"label":{"tr":"PVPI","en":"PVPI","es":"PVPI"},"unit":{"tr":"oran","en":"ratio","es":"cociente"},"meaning":{"tr":"EVLW’nin pulmoner kan hacmine oranı; alveolokapiller geçirgenlik göstergesi. [9]","en":"Ratio of EVLW to pulmonary blood volume; marker of alveolar–capillary permeability. [9]","es":"Cociente entre EVLW y volumen sanguíneo pulmonar; marcador de permeabilidad alveolocapilar. [9]"},"interpretation":{"tr":"Üretici referansı 1,0–3,0. [8] Hidrostatik ödemde ARDS’ye göre daha düşüktür; 3 değeri iki ödem türünü ayırmada en iyi eşik olarak bulunmuştur. [9]","en":"Manufacturer reference 1.0–3.0. [8] Lower in hydrostatic oedema than in ARDS; a value of 3 was the best threshold for distinguishing the two. [9]","es":"Referencia del fabricante: 1,0–3,0. [8] Es menor en el edema hidrostático que en el SDRA; un valor de 3 fue el mejor umbral para distinguir ambos. [9]"},"context":{"tr":"ARDS tanısı klinik tanım ölçütlerine (Berlin tanımı) dayanır; PVPI yalnızca destekleyici bilgi sağlar. [12]","en":"ARDS is diagnosed by clinical definition criteria (Berlin Definition); PVPI provides supportive information only. [12]","es":"El SDRA se diagnostica con criterios clínicos de definición (definición de Berlín); el PVPI solo aporta información de apoyo. [12]"},"range":{"tr":"Bilgi yok","en":"No data available","es":"Sin datos disponibles"},"target":{"tr":"Üretici referansı: 1,0–3,0; tek başına tanı koydurmaz. [8]","en":"Manufacturer reference: 1.0–3.0; not diagnostic on its own. [8]","es":"Referencia del fabricante: 1,0–3,0; no es diagnóstico por sí solo. [8]"},"numeric":{"type":"manufacturer_reference","population":"adult"},"verify":{"definition":"source_supported","interpretation":"source_supported","numeric":"source_supported_context_limited"}}],"references":[{"n":1,"title":"HemoSphere Advanced Monitor Operator’s Manual DOC-0243444A","publisher":"Edwards Lifesciences","year":"2024; kılavuz 7.8, yazılım 03.02.xxx.xxx","url":"https://eifu.edwards.com/eifu/5970f1b346e0fb00015e5f4d/DOC-0243444A.pdf","doi":null,"type":"ifu"},{"n":2,"title":"Welcome to Getinge","publisher":"Getinge","year":null,"url":"https://www.getinge.com/INT","doi":null,"type":"quick_guide"},{"n":3,"title":"Getinge Pulsiocare","publisher":"Getinge","year":null,"url":"https://www.getinge.com/sea/products/pulsiocare/","doi":null,"type":"manufacturer"},{"n":4,"title":"Hemodynamic Monitoring Training Material","publisher":"Getinge","year":null,"url":"https://www.getinge.com/sea/covid-19-resource-center/hemodynamic-monitoring-training-material/","doi":null,"type":"manufacturer"},{"n":5,"title":"[Getinge brochure: PiCCO Technology (MCV00067845, US)]","publisher":"Getinge","year":null,"url":"https://www2.getinge.com/dam/hospital/documents/english/mcv00067845_cc_picco_technology_brochure_us_6_lo-res-en-us.pdf","doi":null,"type":"manufacturer"},{"n":6,"title":"Prediction of fluid responsiveness: an update","publisher":"Annals of Intensive Care","year":"2016","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5114218/","doi":null,"type":"peer_reviewed"},{"n":7,"title":"Guideline for Disinfection and Sterilization: Summary Recommendations","publisher":"CDC","year":"2008; web özeti 2023","url":"https://www.cdc.gov/infection-control/hcp/disinfection-sterilization/summary-recommendations.html","doi":null,"type":"guideline"},{"n":8,"title":"PiCCO Hemodynamic Decision Model – Hemodynamic Normal Values (MX-9493)","publisher":"Getinge","year":"2026","url":"https://www.getinge.com/dam/hospital/documents/english/picco_decision_tree-46004-en.pdf","doi":null,"type":"quick_guide"},{"n":9,"title":"Transpulmonary thermodilution: advantages and limits (Monnet X, Teboul JL). Crit Care 21:147","publisher":"Critical Care","year":"2017","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5474867/","doi":"10.1186/s13054-017-1739-5","type":"peer_reviewed"},{"n":10,"title":"PiCCO Trouble Shooting Guide – for PulsioFlex with PiCCO module","publisher":"Getinge","year":null,"url":"https://www.getinge.com/assets/content/PiCCO_TSG-US/index.html","doi":null,"type":"manufacturer"},{"n":11,"title":"K072735 – Pulsion PiCCO-2, Model 8500: 510(k) clearance letter and Indications for Use","publisher":"U.S. Food and Drug Administration","year":"2007","url":"https://www.accessdata.fda.gov/cdrh_docs/pdf7/K072735.pdf","doi":null,"type":"regulatory"},{"n":12,"title":"Acute respiratory distress syndrome: the Berlin Definition","publisher":"JAMA","year":"2012","url":"https://pubmed.ncbi.nlm.nih.gov/22797452/","doi":"10.1001/jama.2012.5669","type":"peer_reviewed"},{"n":13,"title":"Main limitations of transpulmonary thermodilution: set targets (Sánchez-Sánchez M et al.). Crit Care 21:242","publisher":"Critical Care","year":"2017","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5604349/","doi":"10.1186/s13054-017-1833-8","type":"peer_reviewed"}],"images":[{"src":"content/img/picco-urun.jpg","kind":"photo","alt":{"tr":"PiCCO (Pulsiocare) — üretici görseli","en":"PiCCO (Pulsiocare) — manufacturer image","es":"PiCCO (Pulsiocare) — imagen del fabricante"},"caption":{"tr":"Üretici görseli; model ve yapılandırma ülkeye göre değişebilir.","en":"Manufacturer image; model and configuration may vary by country.","es":"Imagen del fabricante; el modelo y la configuración pueden variar según el país."},"credit":"Getinge (Pulsion)","sourceUrl":"https://www.getinge.com/sea/products/pulsiocare/","rights":"publication_permission_declared_by_site_owner","rightsDate":"2026-10-07"},{"src":"content/img/picco-sema.svg","kind":"schematic","alt":{"tr":"PiCCO ile Pulsiocare için temsili bağlantı bölgesi","en":"Representative connection site for PiCCO with Pulsiocare","es":"Zona de conexión representativa de PiCCO con Pulsiocare"},"caption":{"tr":"Genel uygulama şemasıdır; sensörün kesin anatomik yerleşimini göstermez.","en":"General application diagram; it does not show the exact anatomical position of the sensor.","es":"Esquema general de aplicación; no muestra la posición anatómica exacta del sensor."}}],"external":[],"photoWithheld":false};
